/**
 * @param {number} left
 * @param {number} right
 * @return {string}
 */
var abbreviateProduct = function(left, right) {
    let product = 1n;
    let twos = 0;
    let fives = 0;

    for (let i = left; i <= right; i++) {
        let value = i;

        while (value % 2 === 0) {
            twos++;
            value /= 2;
        }

        while (value % 5 === 0) {
            fives++;
            value /= 5;
        }

        product *= BigInt(value);
    }

    const zeros = Math.min(twos, fives);
    product *= 2n ** BigInt(twos - zeros);
    product *= 5n ** BigInt(fives - zeros);

    const digits = product.toString();

    if (digits.length > 10) {
        return `${digits.slice(0, 5)}...${digits.slice(-5)}e${zeros}`;
    }

    return `${digits}e${zeros}`;
};
