 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length;
    const n = grid[0].length;
    const roof = m * n;
    const work = grid.map(row => row.slice());
    const existed = new Array(hits.length).fill(false);

    for (let i = 0; i < hits.length; i++) {
        const [r, c] = hits[i];
        if (work[r][c] === 1) {
            existed[i] = true;
            work[r][c] = 0;
        }
    }

    const parent = new Int32Array(roof + 1);
    const size = new Int32Array(roof + 1);

    for (let i = 0; i <= roof; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const find = (x) => {
        let root = x;
        while (parent[root] !== root) {
            root = parent[root];
        }
        while (parent[x] !== x) {
            const next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    };

    const union = (a, b) => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    const getRoofSize = () => size[find(roof)];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (work[r][c] === 0) continue;

            const index = r * n + c;

            if (r === 0) union(index, roof);
            if (r > 0 && work[r - 1][c] === 1) {
                union(index, (r - 1) * n + c);
            }
            if (c > 0 && work[r][c - 1] === 1) {
                union(index, r * n + c - 1);
            }
        }
    }

    const result = new Array(hits.length).fill(0);
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    for (let i = hits.length - 1; i >= 0; i--) {
        if (!existed[i]) continue;

        const [r, c] = hits[i];
        const index = r * n + c;
        const before = getRoofSize();

        work[r][c] = 1;

        if (r === 0) union(index, roof);

        for (const [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;

            if (
                nr >= 0 && nr < m &&
                nc >= 0 && nc < n &&
                work[nr][nc] === 1
            ) {
                union(index, nr * n + nc);
            }
        }

        const after = getRoofSize();
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
};
