/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007;
    const BASE = 32768;

    const multiplyMod = (a, b) => {
        const high = Math.floor(b / BASE);
        const low = b % BASE;
        return (((a * high) % MOD) * BASE + a * low) % MOD;
    };

    arr.sort((a, b) => a - b);

    const n = arr.length;
    const dp = new Array(n).fill(1);
    const index = new Map();

    for (let i = 0; i < n; i++) {
        index.set(arr[i], i);
    }

    let answer = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] !== 0) continue;

            const other = arr[i] / arr[j];
            const k = index.get(other);

            if (k !== undefined && k < i) {
                dp[i] = (dp[i] + multiplyMod(dp[j], dp[k])) % MOD;
            }
        }

        answer = (answer + dp[i]) % MOD;
    }

    return answer;
};
```

