/**
 * @param {number} n
 * @return {number}
 */
var countVowelPermutation = function(n) {
    const MOD = 1000000007;

    let a = 1;
    let e = 1;
    let i = 1;
    let o = 1;
    let u = 1;

    for (let length = 2; length <= n; length++) {
        const nextA = (e + i + u) % MOD;
        const nextE = (a + i) % MOD;
        const nextI = (e + o) % MOD;
        const nextO = i;
        const nextU = (i + o) % MOD;

        a = nextA;
        e = nextE;
        i = nextI;
        o = nextO;
        u = nextU;
    }

    return (a + e + i + o + u) % MOD;
};
