/**
 * @param {number} n
 * @return {number}
 */
var clumsy = function(n) {
    const stack = [n];
    const operations = ['*', '/', '+', '-'];
    let operationIndex = 0;

    for (let value = n - 1; value >= 1; value--) {
        const operation = operations[operationIndex % 4];

        if (operation === '*') {
            stack[stack.length - 1] *= value;
        } else if (operation === '/') {
            stack[stack.length - 1] = Math.trunc(stack[stack.length - 1] / value);
        } else if (operation === '+') {
            stack.push(value);
        } else {
            stack.push(-value);
        }

        operationIndex++;
    }

    return stack.reduce((sum, value) => sum + value, 0);
};
