```javascript
/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.maxValue = 100000;

    this.countTree = new Int32Array(this.maxValue + 1);
    this.sumTree = new Float64Array(this.maxValue + 1);

    this.queue = [];
    this.head = 0;
    this.size = 0;

    this.searchBit = 1;
    while (this.searchBit * 2 <= this.maxValue) {
        this.searchBit *= 2;
    }
};

MKAverage.prototype.update = function(value, countDelta) {
    const sumDelta = value * countDelta;

    for (let i = value; i <= this.maxValue; i += i & -i) {
        this.countTree[i] += countDelta;
        this.sumTree[i] += sumDelta;
    }
};

MKAverage.prototype.prefixCount = function(index) {
    let result = 0;

    for (let i = index; i > 0; i -= i & -i) {
        result += this.countTree[i];
    }

    return result;
};

MKAverage.prototype.prefixSum = function(index) {
    let result = 0;

    for (let i = index; i > 0; i -= i & -i) {
        result += this.sumTree[i];
    }

    return result;
};

MKAverage.prototype.findByOrder = function(order) {
    let index = 0;
    let accumulatedCount = 0;

    for (let bit = this.searchBit; bit > 0; bit = Math.floor(bit / 2)) {
        const next = index + bit;

        if (
            next <= this.maxValue &&
            accumulatedCount + this.countTree[next] < order
        ) {
            index = next;
            accumulatedCount += this.countTree[next];
        }
    }

    return index + 1;
};

MKAverage.prototype.sumOfSmallest = function(count) {
    if (count <= 0) {
        return 0;
    }

    const boundary = this.findByOrder(count);
    const countBefore = this.prefixCount(boundary - 1);
    const sumBefore = this.prefixSum(boundary - 1);

    return sumBefore + (count - countBefore) * boundary;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this.update(num, 1);
    this.size++;

    if (this.size > this.m) {
        const removed = this.queue[this.head++];
        this.update(removed, -1);
        this.size--;
    }
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.size < this.m) {
        return -1;
    }

    const middleSum =
        this.sumOfSmallest(this.m - this.k) -
        this.sumOfSmallest(this.k);

    return Math.floor(middleSum / (this.m - 2 * this.k));
};

/** 
 * Your MKAverage object will be instantiated and called as such:
 * var obj = new MKAverage(m, k)
 * obj.addElement(num)
 * var param_2 = obj.calculateMKAverage()
 */
