        used[state] = used[Math.floor(state / 3)] + state % 3;
    }

    for (let state = 0; state < totalStates; state++) {
        if (dp[state] < 0) continue;

        const index = used[state];
        if (index === nums.length) {
            answer = Math.max(answer, dp[state]);
            continue;
