        for (let slot = 0; slot < numSlots; slot++) {
            if (Math.floor(state / powers[slot]) % 3 < 2) {
                const nextState = state + powers[slot];
                const score = dp[state] + (nums[index] & (slot + 1));
                dp[nextState] = Math.max(dp[nextState], score);
            }
        }
    }

    return answer;
