var maximumBeauty = function(flowers, newFlowers, target, full, partial) {
    const incomplete = [];

    for (const count of flowers) {
        if (count < target) {
            incomplete.push(count);
        }
    }

    incomplete.sort((a, b) => a - b);

    const m = incomplete.length;
    const n = flowers.length;
    const prefix = new Array(m + 1).fill(0);

    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + incomplete[i];
    }

    let answer = 0;
    let completionCost = 0;

    for (let completed = 0; completed <= m; completed++) {
        if (completionCost > newFlowers) break;

        const remainingCount = m - completed;
        const completeGardens = n - remainingCount;
        let beauty = completeGardens * full;

        if (remainingCount > 0) {
            const remainingFlowers = newFlowers - completionCost;

            let left = 1;
            let right = remainingCount;
            let raisedCount = 1;

            while (left <= right) {
                const mid = Math.floor((left + right) / 2);
                const cost = incomplete[mid - 1] * mid - prefix[mid];

                if (cost <= remainingFlowers) {
