/**
 * @param {number[]} nums
 * @return {number}
 */
var numOfWays = function(nums) {
    const MOD = 1000000007n;
    const n = nums.length;

    const modPow = (base, exponent) => {
        let result = 1n;
        while (exponent > 0n) {
            if (exponent & 1n) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1n;
        }
        return result;
    };

    const factorial = new Array(n + 1).fill(1n);
    const inverseFactorial = new Array(n + 1).fill(1n);

    for (let i = 1; i <= n; i++) {
        factorial[i] = (factorial[i - 1] * BigInt(i)) % MOD;
    }

    inverseFactorial[n] = modPow(factorial[n], MOD - 2n);
    for (let i = n; i >= 1; i--) {
        inverseFactorial[i - 1] =
            (inverseFactorial[i] * BigInt(i)) % MOD;
    }

    const combinations = (total, choose) => {
        return (
            factorial[total] *
            inverseFactorial[choose] %
            MOD *
            inverseFactorial[total - choose]
        ) % MOD;
    };

    const countWays = (values) => {
        if (values.length <= 2) return 1n;

        const left = [];
        const right = [];
        const root = values[0];

        for (let i = 1; i < values.length; i++) {
            if (values[i] < root) {
                left.push(values[i]);
            } else {
                right.push(values[i]);
            }
        }

        const interleavings = combinations(
            left.length + right.length,
            left.length
        );

        return (
            interleavings *
            countWays(left) %
            MOD *
            countWays(right)
        ) % MOD;
    };

    return Number((countWays(nums) - 1n + MOD) % MOD);
};
