var medianSlidingWindow = function(nums, k) {
    const sorted = [...nums].sort((a, b) => a - b);
    const values = [];

    for (const value of sorted) {
        if (values.length === 0 || values[values.length - 1] !== value) {
            values.push(value);
        }
    }

    const index = new Map();
    for (let i = 0; i < values.length; i++) {
        index.set(values[i], i + 1);
    }

    const tree = new Int32Array(values.length + 1);

    const update = (position, delta) => {
        for (let i = position; i < tree.length; i += i & -i) {
            tree[i] += delta;
        }
    };

    const kth = (rank) => {
        let position = 0;
        let step = 1;

        while (step * 2 <= values.length) {
            step *= 2;
        }

        for (; step > 0; step = Math.floor(step / 2)) {
            const next = position + step;
            if (next <= values.length && tree[next] < rank) {
                position = next;
                rank -= tree[next];
            }
        }

        return values[position];
    };

    const result = [];

    for (let right = 0; right < nums.length; right++) {
        update(index.get(nums[right]), 1);

        if (right >= k) {
            update(index.get(nums[right - k]), -1);
        }

        if (right >= k - 1) {
            if (k % 2 === 1) {
                result.push(kth((k + 1) / 2));
            } else {
                const leftMiddle = kth(k / 2);
