/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();
    const BASE = 32;

    const dfs = (players, first, second) => {
        const reflectedFirst = players + 1 - second;
        const reflectedSecond = players + 1 - first;

        if (
            reflectedFirst < first ||
            (reflectedFirst === first && reflectedSecond < second)
        ) {
            first = reflectedFirst;
            second = reflectedSecond;
        }

        if (first + second === players + 1) {
            return [1, 1];
        }

        const key = `${players},${first},${second}`;
        if (memo.has(key)) {
            return memo.get(key);
        }

        let states = new Set([0]);

        const processChoices = (choices) => {
            const nextStates = new Set();

            for (const state of states) {
                const beforeFirst = Math.floor(state / BASE);
                const beforeSecond = state % BASE;

                for (const winner of choices) {
                    const nextBeforeFirst =
                        beforeFirst + (winner < first ? 1 : 0);
                    const nextBeforeSecond =
                        beforeSecond + (winner < second ? 1 : 0);

                    nextStates.add(nextBeforeFirst * BASE + nextBeforeSecond);
                }
            }

            states = nextStates;
        };

        for (let left = 1; left <= Math.floor(players / 2); left++) {
            const right = players + 1 - left;

            if (left === first || right === first) {
                processChoices([first]);
            } else if (left === second || right === second) {
                processChoices([second]);
            } else {
                processChoices([left, right]);
            }
        }

        if (players % 2 === 1) {
            processChoices([(players + 1) >> 1]);
        }

        const nextPlayers = Math.ceil(players / 2);
        let earliest = Infinity;
        let latest = -Infinity;

        for (const state of states) {
            const nextFirst = Math.floor(state / BASE) + 1;
            const nextSecond = (state % BASE) + 1;
            const [childEarliest, childLatest] = dfs(
                nextPlayers,
                nextFirst,
                nextSecond
            );

            earliest = Math.min(earliest, childEarliest + 1);
            latest = Math.max(latest, childLatest + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    };

    return dfs(n, firstPlayer, secondPlayer);
};
